trans = {('q0','0'):('q0','0','R'), ('q0','1'):('qaccept','1','R'), ('q0','□'):('qreject','□','R')}
def run(s):
    tape = list(s) + ['□'] * 6
    head = 0
    state = 'q0'
    for step in range(20):
        a = tape[head]
        if (state, a) not in trans:
            return 0
        state, write, move = trans[(state, a)]
        tape[head] = write
        if state == 'qaccept':
            return 1
        if state == 'qreject':
            return 0
        head += 1 if move == 'R' else -1
        if head < 0:
            tape.insert(0, '□')
            head = 0
        elif head >= len(tape):
            tape.append('□')
    return 0
print(run('001'))
print(run('000'))
